             reset_ar_accepted, reset_ar_waited);
      bfm_aw(4'd15, addr_for(4), 8'd0, 4,
             reset_aw_accepted, reset_aw_waited);
      begin
        @(negedge clk);
        s_wdata = 32'hdead_beef;
        s_wstrb = 4'hf;
        s_wlast = 1'b1;
        s_wvalid = 1'b1;
        repeat (3) @(posedge clk);
        @(negedge clk);
        s_wvalid = 1'b0;
      end
      begin
        repeat (6) @(posedge clk);
        @(negedge clk);
        rst_n = 1'b1;
      end
