    // either ignores them or accepts and discards them; neither may produce a
    // slave response. Valid is time-bounded so an empty DUT cannot hang the TB.
    discard_window = 1'b1;
    repeat (2) @(negedge clk);
    fork
      begin
        @(negedge clk);
        m_rid = old_rmid;
        m_rdata = old_rdata;
        m_rresp = 2'b00;
        m_rlast = 1'b1;
        m_rvalid = 1'b1;
        repeat (3) @(posedge clk);
        @(negedge clk);
        m_rvalid = 1'b0;
