    send_read_txn(r5);
    need_rd_done(r5);
    send_read_txn(r4);
    need_rd_done(r4);
    send_read_txn(r3);
    need_rd_done(r3);
    send_read_txn(r1);
    need_rd_done(r1);
    send_read_txn(r1b);
    need_rd_done(r1b);

